+  return name;
 }
+
+const NAME_PATTERN = /^[A-Z_][A-Z0-9_]*$/;
+const PLAIN_VALUE = /^[A-Za-z0-9_@%+=:,./-]*$/;
+const ESCAPES: Record<string, string> = { "\\": "\\\\", '"': '\\"', $: "\\$", "\n": "\\n", "\r": "\\r" };

 /** Render variables as the lines of a dotenv file. */
 export function renderEnvFile(vars: Record<string, string>): string {
-  throw new Error("not implemented");
+  let text = "";
+  for (const name of Object.keys(vars).sort()) {
+    if (!NAME_PATTERN.test(name)) throw new RangeError(`invalid variable name: ${JSON.stringify(name)}`);
+    const value = vars[name];
+    const rendered = PLAIN_VALUE.test(value) ? value : `"${value.replace(/[\\"$\n\r]/g, (c) => ESCAPES[c])}"`;
+    text += `${name}=${rendered}\n`;
+  }
+  return text;
 }

